"use client";

/** A twentieth of a second of silence, played to unlock audio on iPhones. */
const SILENCE =
  "data:audio/mpeg;base64,";

const unlocked = new WeakSet<HTMLAudioElement>();

/**
 * iPhone Safari only lets a page play sound it started from a tap. Called in
 * a tap handler, this plays a moment of silence on `audio`, after which the
 * player can start and stop narration on it freely.
 */
export function unlockAudio(audio: HTMLAudioElement) {
  if (unlocked.has(audio)) return;
  unlocked.add(audio);
  audio.src = SILENCE;
  // Interrupted by the first clip loading, which is fine: the tap counted.
  audio.play().catch(() => {});
}
